  1	import * as React from 'react';
  2	import { HashRouter, useHistory, useLocation } from 'react-router-dom';
  3	import { IHhhhSpaProps } from './IHhhhSpaProps';
  4	import SpaLeftNavigation from './SpaLeftNavigation';
  5	import SpaBreadcrumb from './SpaBreadcrumb';
  6	import SpaNavigationInterceptor from './SpaNavigationInterceptor';
  7	import SpaTopNavigation from './SpaTopNavigation';
  8	import FeatureKeepAlive from './FeatureKeepAlive';
  9	import SpaErrorBoundary from './SpaErrorBoundary';
 10	import styles from './HhhhSpa.module.scss';
 11	import PageSkeleton from '../common/PageSkeleton';
 12	import { setActiveScope, wasScopeAborted, clearScopeAborted } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/requestScope';
 13	
 14	/**
 15	 * Phase-2: shell lazy-loads feature entries only (UAT-style boundaries).
 16	 * Page business logic stays under src/pages — features are thin wrappers.
 17	 * Keep-alive + NavLinks / search sync unchanged.
 18	 */
 19	const TeamPortfolioFeature = React.lazy(
 20	  () => import('../features/teamPortfolio/TeamPortfolioFeature')
 21	);
 22	const ProjectOverviewFeature = React.lazy(
 23	  () => import('../features/projectOverview/ProjectOverviewFeature')
 24	);
 25	const CreateTaskFeature = React.lazy(
 26	  () => import('../features/createTask/CreateTaskFeature')
 27	);
 28	const PortfolioProfileFeature = React.lazy(
 29	  () => import('../features/portfolioProfile/PortfolioProfileFeature')
 30	);
 31	const TaskProfileFeature = React.lazy(
 32	  () => import('../features/taskProfile/TaskProfileFeature')
 33	);
 34	const PxcProfileFeature = React.lazy(
 35	  () => import('../features/pxcProfile/PxcProfileFeature')
 36	);
 37	const StaticDashboardFeature = React.lazy(
 38	  () => import('../features/staticDashboard/StaticDashboardFeature')
 39	);
 40	const DashboardFeature = React.lazy(
 41	  () => import('../features/dashboard/DashboardFeature')
 42	);
