 58	function useSearchKey(): string {
 59	  const [searchKey, setSearchKey] = React.useState(() => window.location.search || '');
 60	
 61	  React.useEffect(() => {
 62	    const onChange = (): void => {
 63	      setSearchKey(window.location.search || '');
 64	    };
 65	    window.addEventListener('popstate', onChange);
 66	    window.addEventListener('hashchange', onChange);
 67	    window.addEventListener('spa-search-change', onChange);
 68	    return () => {
 69	      window.removeEventListener('popstate', onChange);
 70	      window.removeEventListener('hashchange', onChange);
 71	      window.removeEventListener('spa-search-change', onChange);
 72	    };
 73	  }, []);
 74	
 75	  return searchKey;
 76	}
 77	
 78	/**
 79	 * UAT-style outlet: landing tools stay mounted (hide/show).
 80	 * Detail profiles remount when query params change so legacy search readers work.
 81	 */
 82	function FeatureOutlet(props: { pageProps: any }): React.ReactElement {
 83	  const { pageProps } = props;
 84	
 85	  // Prefetch profile chunks while landing tools are open so the first
 86	  // Team-Portfolio → Profile click does not flash Suspense PageSkeleton.
 87	  React.useEffect(() => {
 88	    void import('../features/portfolioProfile/PortfolioProfileFeature');
 89	    void import('../features/taskProfile/TaskProfileFeature');
 90	    void import('../features/pxcProfile/PxcProfileFeature');
 91	  }, []);
 92	  const location = useLocation();
 93	  const history = useHistory();
 94	  const searchKey = useSearchKey();
 95	  const pathname = location.pathname || '';
 96	
 97	  // Keep last profile remount key so clearing ?taskId on leave does not remount with nulls
 98	  const portfolioKeyRef = React.useRef('portfolio-profile');
 99	  const taskKeyRef = React.useRef('task-profile');
100	  const pxcKeyRef = React.useRef('pxc-profile');
101	
102	  React.useEffect(() => {
103	    if (pathname === '/' || pathname === '') {
104	      history.replace('/team-portfolio');
105	    }
106	  }, [pathname, history]);
107	
108	  const isTeamPortfolio = pathname.indexOf('/team-portfolio') === 0;
109	  const isProjectOverview = pathname.indexOf('/project-overview') === 0;
110	  const isCreateTask = pathname.indexOf('/create-task') === 0;
111	  const isPortfolioProfile = pathname.indexOf('/portfolio-profile') === 0;
112	  const isTaskProfile = pathname.indexOf('/task-profile') === 0;
113	  const isPxcProfile = pathname.indexOf('/pxc-profile') === 0;
114	  const isOmt = pathname.indexOf('/omt') === 0;
115	  const isDashboard = pathname.indexOf('/dashboard') === 0;
116	
117	  React.useEffect(() => {
118	    if (isOmt) {
119	      document.title = "Operational Management Tool";
120	    } else if (isDashboard) {
121	      document.title = "Dashboard";
122	    } else if (isTeamPortfolio || isProjectOverview || isCreateTask) {
123	      document.title = "Task Management";
124	    }
125	  }, [isTeamPortfolio, isProjectOverview, isCreateTask, isOmt, isDashboard]);
126	
127	  /**
128	   * List tools never set document.title themselves. Hierarchical profiles do
129	   * (`C246-…`, `PX123-…`), and keep-alive leaves those pages mounted, so the
130	   * tab title stuck after leaving for Create Task / OMT. Restore list titles
131	   * here; leave profile routes to the item loaders so PXC/portfolio/task titles
132	   * stay `{ID}-{Title}`.
133	   */
134	  React.useEffect(() => {
135	    if (isCreateTask) {
136	      document.title = 'Create Task';
137	      return;
138	    }
139	    if (isOmt) {
140	      document.title = 'OMT';
141	      return;
142	    }
143	    if (isDashboard) {
144	      document.title = 'Dashboard';
145	      return;
146	    }
147	    if (isTeamPortfolio) {
148	      document.title = 'Team Portfolio';
149	      return;
150	    }
151	    if (isProjectOverview) {
152	      document.title = 'PXC Management Overview';
153	    }
154	  }, [isCreateTask, isOmt, isDashboard, isTeamPortfolio, isProjectOverview]);
155	
156	  /**
157	   * Team Portfolio (and profiles) write Portfolio Type color onto document
158	   * `--SiteColor`. Keep-alive leaves that value in place, so Project Overview /
159	   * Create Task / OMT incorrectly stayed Service-green. Restore the default
160	   * site blue for those non-portfolio tabs only — Tailwind `var(--SiteColor)`
161	   * consumers pick it up with no business-logic changes.
162	   */
163	  React.useEffect(() => {
164	    if (isProjectOverview || isCreateTask || isOmt || isDashboard) {
165	      document.documentElement.style.setProperty('--SiteColor', '#2F5596');
166	    }
167	  }, [isProjectOverview, isCreateTask, isOmt, isDashboard]);
168	
169	  /**
170	   * Item ids are mirrored into window.location.search by navigateSpa (legacy
171	   * readers). HashRouter's location.search is often empty while the real URL
172	   * is `workbench.aspx?ProjectId=12920#/pxc-profile`. Prefer window search so
173	   * each profile item gets its own cancellable scope — otherwise every PXC
174	   * shares `pxc-profile`, setActiveScope no-ops, and Documents batches stack.
175	   */
176	  const hashQuery = React.useMemo(() => {
177	    if (searchKey && searchKey.length > 1) {
178	      return searchKey;
179	    }
180	    if (location.search && location.search.length > 1) {
181	      return location.search;
182	    }
183	    if (window.location.hash.indexOf('?') !== -1) {
184	      return window.location.hash.slice(window.location.hash.indexOf('?'));
185	    }
186	    return '';
187	  }, [location.search, location.pathname, searchKey]);
188	
189	  // Publish the active route to the request layer. Leaving a profile aborts
190	  // every SharePoint call it still had in flight (see requestScope).
191	  const scopeId = React.useMemo(() => {
192	    if (isTeamPortfolio) return 'team-portfolio';
193	    if (isProjectOverview) return 'project-overview';
194	    if (isCreateTask) return 'create-task';
195	    if (isOmt) return 'omt';
196	    if (isDashboard) return 'dashboard';
197	
198	    if (isPortfolioProfile) return `portfolio-profile${hashQuery}`;
199	    if (isTaskProfile) return `task-profile${hashQuery}`;
200	    if (isPxcProfile) return `pxc-profile${hashQuery}`;
201	    return 'global';
202	  }, [
203	    isTeamPortfolio, isProjectOverview, isCreateTask, isOmt, isDashboard,
204	    isPortfolioProfile, isTaskProfile, isPxcProfile, hashQuery
205	  ]);
206	
207	  // Set during render, not in an effect: child effects (which start the data
208	  // loads) run before parent effects, so an effect here would file a profile's
209	  // first requests under the previous route and they'd never be aborted.
210	  // setActiveScope is idempotent and no-ops when the scope is unchanged.
211	  setActiveScope(scopeId);
212	
213	  /**
214	   * Returning to a profile whose load we cancelled: features stay mounted, so
215	   * its effects will not re-run by themselves and it would render empty
216	   * forever. Bumping the remount key gives it a clean mount and a fresh load.
217	   */
218	  const [reloadNonce, setReloadNonce] = React.useState({ portfolio: 0, task: 0, pxc: 0 });
219	  const isProfileRoute = isPortfolioProfile || isTaskProfile || isPxcProfile;
220	  React.useEffect(() => {
221	    if (!isProfileRoute || !wasScopeAborted(scopeId)) {
222	      return;
223	    }
224	    clearScopeAborted(scopeId);
225	    /**
226	     * PXC used to skip the remount whenever an in-memory seed existed, on the
227	     * grounds that restoring the hidden instance was enough. It is not: we only
228	     * reach this branch because the scope WAS aborted, so that instance had its
229	     * in-flight requests cancelled part-way through. The seed carries the header
230	     * row alone — deliverables, documents and tasks were left unloaded — so
231	     * reopening the same PXC showed a blank profile.
232	     *
233	     * Portfolio Profile and Task Profile have always remounted here and reload
234	     * cleanly, so PXC takes the same path rather than a special case.
235	     */
236	    const which = isPortfolioProfile ? 'portfolio' : isTaskProfile ? 'task' : 'pxc';
237	    setReloadNonce((n) => ({ ...n, [which]: n[which] + 1 }));
238	  }, [isProfileRoute, isPortfolioProfile, isTaskProfile, isPxcProfile, scopeId]);
239	
240	  if (isPortfolioProfile && searchKey && searchKey.indexOf('taskId=') !== -1) {
241	    portfolioKeyRef.current = `portfolio-profile-${searchKey}`;
242	  }
243	  if (isTaskProfile && searchKey && searchKey.indexOf('taskId=') !== -1) {
244	    taskKeyRef.current = `task-profile-${searchKey}`;
245	  }
246	  if (isPxcProfile && searchKey && searchKey.indexOf('ProjectId=') !== -1) {
247	    pxcKeyRef.current = `pxc-profile-${searchKey}`;
248	  }
249	
250	  const portfolioKey = `${portfolioKeyRef.current}-${reloadNonce.portfolio}`;
251	  const taskKey = `${taskKeyRef.current}-${reloadNonce.task}`;
252	  const pxcKey = `${pxcKeyRef.current}-${reloadNonce.pxc}`;
253	
254	  return (
255	    <>
256	      <FeatureKeepAlive active={isTeamPortfolio} featureId="team-portfolio">
257	        <SuspensePage variant="team-portfolio" label="Team Portfolio">
258	          <TeamPortfolioFeature pageProps={pageProps} />
259	        </SuspensePage>
260	      </FeatureKeepAlive>
261	
262	      <FeatureKeepAlive active={isProjectOverview} featureId="project-overview">
263	        <SuspensePage variant="project-overview" label="Project Overview">
264	          <ProjectOverviewFeature pageProps={pageProps} />
265	        </SuspensePage>
266	      </FeatureKeepAlive>
267	
268	      <FeatureKeepAlive active={isCreateTask} featureId="create-task" keepAlive={false}>
269	        <SuspensePage variant="create-task" label="Create Task">
270	          <CreateTaskFeature pageProps={pageProps} />
271	        </SuspensePage>
272	      </FeatureKeepAlive>
273	
274	      <FeatureKeepAlive active={isPortfolioProfile} featureId="portfolio-profile">
275	        <SuspensePage label="Portfolio Profile">
276	          <PortfolioProfileFeature
277	            pageProps={pageProps}
278	            remountKey={portfolioKey}
279	          />
280	        </SuspensePage>
281	      </FeatureKeepAlive>
282	
283	      <FeatureKeepAlive active={isTaskProfile} featureId="task-profile">
284	        <SuspensePage label="Task Profile">
285	          <TaskProfileFeature
286	            pageProps={pageProps}
287	            remountKey={taskKey}
288	          />
289	        </SuspensePage>
290	      </FeatureKeepAlive>
291	
292	      <FeatureKeepAlive active={isPxcProfile} featureId="pxc-profile">
293	        <SuspensePage label="PXC Profile">
294	          <PxcProfileFeature
295	            pageProps={pageProps}
296	            remountKey={pxcKey}
297	          />
298	        </SuspensePage>
299	      </FeatureKeepAlive>
300	
301	      <FeatureKeepAlive active={isOmt} featureId="omt">
302	        <SuspensePage variant="omt" label="OMT">
303	          <StaticDashboardFeature pageProps={pageProps} />
304	        </SuspensePage>
305	      </FeatureKeepAlive>
306	
307	      <FeatureKeepAlive active={isDashboard} featureId="dashboard">
308	        <SuspensePage variant="default" label="Dashboard">
309	          <DashboardFeature pageProps={pageProps} />
310	        </SuspensePage>
311	      </FeatureKeepAlive>
312	    </>
313	  );
314	}
315	
316	/**
317	 * One SPA web part shell — HashRouter + keep-alive + feature lazy entries.
318	 */
319	export default function HhhhSpaApp(props: IHhhhSpaProps): React.ReactElement<IHhhhSpaProps> {
320	  const pageProps = React.useMemo(
321	    () => ({
322	      ...props,
323	      AdminconfigrationID: props.AdminConfigrationListID,
324	      AdminConfigrationListID: props.AdminConfigrationListID,
325	      dropdownvalue: 'Component Portfolio'
326	    }),
327	    [props]
328	  );
329	
330	  return (
331	    <HashRouter>
332	      <SpaNavigationInterceptor />
333	      {/* hhhh-spa-webpart: Style.css body rules are compiled to this selector for SPFx */}
334	      <div className={`hhhh-spa-webpart ${styles.hhhhSpaShell}`} style={{ flexDirection: 'column' }}>
335	        <div style={{ flex: '0 0 auto', width: '100%' }}>
336	          <SpaTopNavigation siteUrl={props.siteUrl} context={props.Context} />
337	        </div>
338	        <div style={{ display: 'flex', flex: '1 1 auto', minHeight: 0, minWidth: 0, width: '100%' }}>
339	          <SpaLeftNavigation>
340	            <SpaBreadcrumb />
341	            <FeatureOutlet pageProps={pageProps} />
342	          </SpaLeftNavigation>
343	        </div>
344	      </div>
345	    </HashRouter>
346	  );
347	}

