211	  setActiveScope(scopeId);
212	
213	  /**
214	   * Returning to a profile whose load we cancelled: features stay mounted, so
215	   * its effects will not re-run by themselves and it would render empty
216	   * forever. Bumping the remount key gives it a clean mount and a fresh load.
217	   */
218	  const [reloadNonce, setReloadNonce] = React.useState({ portfolio: 0, task: 0, pxc: 0 });
219	  const isProfileRoute = isPortfolioProfile || isTaskProfile || isPxcProfile;
220	  React.useEffect(() => {
221	    if (!isProfileRoute || !wasScopeAborted(scopeId)) {
222	      return;
223	    }
224	    clearScopeAborted(scopeId);
225	    /**
226	     * PXC used to skip the remount whenever an in-memory seed existed, on the
227	     * grounds that restoring the hidden instance was enough. It is not: we only
228	     * reach this branch because the scope WAS aborted, so that instance had its
229	     * in-flight requests cancelled part-way through. The seed carries the header
230	     * row alone — deliverables, documents and tasks were left unloaded — so
231	     * reopening the same PXC showed a blank profile.
232	     *
233	     * Portfolio Profile and Task Profile have always remounted here and reload
234	     * cleanly, so PXC takes the same path rather than a special case.
235	     */
236	    const which = isPortfolioProfile ? 'portfolio' : isTaskProfile ? 'task' : 'pxc';
237	    setReloadNonce((n) => ({ ...n, [which]: n[which] + 1 }));
238	  }, [isProfileRoute, isPortfolioProfile, isTaskProfile, isPxcProfile, scopeId]);
239	
240	  if (isPortfolioProfile && searchKey && searchKey.indexOf('taskId=') !== -1) {
241	    portfolioKeyRef.current = `portfolio-profile-${searchKey}`;
242	  }
243	  if (isTaskProfile && searchKey && searchKey.indexOf('taskId=') !== -1) {
244	    taskKeyRef.current = `task-profile-${searchKey}`;
245	  }
246	  if (isPxcProfile && searchKey && searchKey.indexOf('ProjectId=') !== -1) {
247	    pxcKeyRef.current = `pxc-profile-${searchKey}`;
248	  }
249	
250	  const portfolioKey = `${portfolioKeyRef.current}-${reloadNonce.portfolio}`;
251	  const taskKey = `${taskKeyRef.current}-${reloadNonce.task}`;
252	  const pxcKey = `${pxcKeyRef.current}-${reloadNonce.pxc}`;
253	
254	  return (
255	    <>
256	      <FeatureKeepAlive active={isTeamPortfolio} featureId="team-portfolio">
