export function skeletonVariantFromPath(pathname: string): PageSkeletonVariant {
  if (pathname.indexOf('/team-portfolio') === 0) return 'team-portfolio';
  if (pathname.indexOf('/project-overview') === 0) return 'project-overview';
  if (pathname.indexOf('/create-task') === 0) return 'create-task';
  if (pathname.indexOf('/omt') === 0) return 'omt';
  return 'default';
}
